(6174236, 910871, 64670, '<td valign="top">Fabulous idea and execution.</td>', 'Fabulous idea and execution.', '2010-09-29 02:08:24.000000', NULL, 1),
(6174237, 911821, 64670, '<td valign="top">Sublime! 10</td>', 'Sublime! 10', '2010-09-29 02:10:29.000000', NULL, 1),
(6174238, 911854, 64670, '<td valign="top">Absolutely WONDERFUL!</td>', 'Absolutely WONDERFUL!', '2010-09-29 02:10:59.000000', NULL, 1),
(6174273, 911664, 108580, '<td valign="top">Pity the Street Name is cut off, would have added more drama to the scene</td>', 'Pity the Street Name is cut off, would have added more drama to the scene', '2010-09-29 03:17:41.000000', NULL, 1),
(6174291, 911744, 96751, '<td valign="top">Great blue!  Really stands out against that brooding sky.</td>', 'Great blue!  Really stands out against that brooding sky.', '2010-09-29 03:42:23.000000', NULL, 1),
(6174293, 911177, 96751, '<td valign="top">Beautifully balanced composition and amazing detail in the tree and sky.  I find that these negatives tend to look "wintery" :-)</td>', 'Beautifully balanced composition and amazing detail in the tree and sky.  I find that these negatives tend to look "wintery" :-)', '2010-09-29 03:44:12.000000', NULL, 1),
(6174294, 911333, 96751, '<td valign="top">Glorious colors.  Love all the lines.  Nice abstract!</td>', 'Glorious colors.  Love all the lines.  Nice abstract!', '2010-09-29 03:45:23.000000', NULL, 1),
(6174295, 911568, 96751, '<td valign="top">LOVE this!  The distortion really works, and the detail of the windows and blur of the people.  Nicely done.</td>', 'LOVE this!  The distortion really works, and the detail of the windows and blur of the people.  Nicely done.', '2010-09-29 03:47:37.000000', NULL, 1),
(6174297, 911542, 96751, '<td valign="top">OH!  Wow.  Just wow.  I''m not sure why it''s so foggy looking, but it so works in this image.  It makes sense that a zebra is a zebra whether in negative or positive image.  Gorgeous.  Few things are as attractive as a zebra rump.</td>', 'OH!  Wow.  Just wow.  I''m not sure why it''s so foggy looking, but it so works in this image.  It makes sense that a zebra is a zebra whether in negative or positive image.  Gorgeous.  Few things are as attractive as a zebra rump.', '2010-09-29 03:49:14.000000', NULL, 1),
(6174298, 910878, 96751, '<td valign="top">How avant garde!  Funky.  Those fishnets are literally GLOWING!</td>', 'How avant garde!  Funky.  Those fishnets are literally GLOWING!', '2010-09-29 03:49:52.000000', NULL, 1),
(6174301, 911526, 96751, '<td valign="top">A true negative.  I just love the reflections on the floor.  Nicely done.</td>', 'A true negative.  I just love the reflections on the floor.  Nicely done.', '2010-09-29 03:50:38.000000', NULL, 1),
(6174302, 911528, 96751, '<td valign="top">This may have the best title in the challenge.  Fabulous capture too.  At first I thought it might be too busy, but it''s really growing on me.</td>', 'This may have the best title in the challenge.  Fabulous capture too.  At first I thought it might be too busy, but it''s really growing on me.', '2010-09-29 03:51:25.000000', NULL, 1),
(6174304, 911264, 96751, '<td valign="top">Stupendous.  LOVE the tones here, and that twig is incredible in blue.  Even a fly looks gorgeous in reverse.</td>', 'Stupendous.  LOVE the tones here, and that twig is incredible in blue.  Even a fly looks gorgeous in reverse.', '2010-09-29 03:52:04.000000', NULL, 1),
(6174305, 911198, 96751, '<td valign="top">Great pattern.</td>', 'Great pattern.', '2010-09-29 03:52:25.000000', NULL, 1),
(6174306, 911845, 96751, '<td valign="top">Stunning colors.  In this reverse, the butterfly looks like part of the flower.  Just beautiful</td>', 'Stunning colors.  In this reverse, the butterfly looks like part of the flower.  Just beautiful', '2010-09-29 03:53:07.000000', NULL, 1),
(6174309, 911182, 96751, '<td valign="top">OMG!  This is too funny.  And wonderful.  How fitting that he is an aquatic blue.</td>', 'OMG!  This is too funny.  And wonderful.  How fitting that he is an aquatic blue.', '2010-09-29 03:53:43.000000', NULL, 1),
(6174310, 911876, 96751, '<td valign="top">Fabulous detail.  I love the strands, but I love the center dots even more.  The backlighting is perfect.</td>', 'Fabulous detail.  I love the strands, but I love the center dots even more.  The backlighting is perfect.', '2010-09-29 03:54:26.000000', NULL, 1),
(6174313, 911868, 96751, '<td valign="top">An inverted ibis is an emu!</td>', 'An inverted ibis is an emu!', '2010-09-29 03:54:55.000000', NULL, 1),
(6174314, 911256, 96751, '<td valign="top">Awesome urban capture.  The pedestrian makes this shot.</td>', 'Awesome urban capture.  The pedestrian makes this shot.', '2010-09-29 03:55:31.000000', NULL, 1),
(6174315, 910837, 96751, '<td valign="top">Andy Warhol!!!</td>', 'Andy Warhol!!!', '2010-09-29 03:56:03.000000', NULL, 1),
