(6174351, 910939, 96751, '<td valign="top">Psychedelic!  Incredible colors.  So intense, you almost miss the figures walking by.</td>', 'Psychedelic!  Incredible colors.  So intense, you almost miss the figures walking by.', '2010-09-29 04:14:12.000000', NULL, 1),
(6174399, 911838, 108069, '<td valign="top">This is really amazing. Right out of a sci-fi cartoon. Excellent work with getting those colors out. One of my three favorites.</td>', 'This is really amazing. Right out of a sci-fi cartoon. Excellent work with getting those colors out. One of my three favorites.', '2010-09-29 06:38:26.000000', NULL, 1),
