(6174958, 911698, 96751, '<td valign="top">Amazing.  I feel like I am underground, but upside down, looking at the exquisiteness of a root system, and imagine the stunning thing growing from it towards the sky.  The shadow/glow on the water adds to the otherworldly effect.  Fabulous.</td>', 'Amazing.  I feel like I am underground, but upside down, looking at the exquisiteness of a root system, and imagine the stunning thing growing from it towards the sky.  The shadow/glow on the water adds to the otherworldly effect.  Fabulous.', '2010-09-29 14:10:26.000000', NULL, 1),
(6174961, 911463, 96751, '<td valign="top">Sensational.  Oh my goodness.  There are just SO many incredible images in this challenge.  But this stands out for it''s deceptive simplicity.  This is a study of lines - straight ones, curved ones, thin ones, thick ones.  And of light and shadow.  Magnificent.</td>', 'Sensational.  Oh my goodness.  There are just SO many incredible images in this challenge.  But this stands out for it''s deceptive simplicity.  This is a study of lines - straight ones, curved ones, thin ones, thick ones.  And of light and shadow.  Magnificent.', '2010-09-29 14:12:12.000000', NULL, 1),
(6174962, 911717, 96751, '<td valign="top">Very, very cool.  Hard angles, soft colors and lines.</td>', 'Very, very cool.  Hard angles, soft colors and lines.', '2010-09-29 14:12:56.000000', NULL, 1),
(6174965, 911812, 96751, '<td valign="top">Terrific motion blur.</td>', 'Terrific motion blur.', '2010-09-29 14:13:39.000000', NULL, 1),
