(6176752, 911177, 108069, '<td valign="top">Really cool, apocalyptical scene. The foreground and the tree are perfectly composed with very nice balance, and the subtle dark clouds in the background and eerie tone to the sky really make it and set off the tree. Wonderfully done.</td>', 'Really cool, apocalyptical scene. The foreground and the tree are perfectly composed with very nice balance, and the subtle dark clouds in the background and eerie tone to the sky really make it and set off the tree. Wonderfully done.', '2010-10-01 08:18:38.000000', NULL, 1),
(6176772, 911802, 108069, '<td valign="top">Really interesting with the pine cone being the source of illumination. Nice colors. Cool shot.</td>', 'Really interesting with the pine cone being the source of illumination. Nice colors. Cool shot.', '2010-10-01 09:08:33.000000', NULL, 1),
(6176776, 911682, 114233, '<td valign="top">I''m assuming a bit of channel swapping here... Nice touch to make it feel more real but looks like some details are lost in the smaller trees</td>', 'I''m assuming a bit of channel swapping here... Nice touch to make it feel more real but looks like some details are lost in the smaller trees', '2010-10-01 09:16:33.000000', NULL, 1),
(6176778, 911812, 114233, '<td valign="top">Nice abstract. Strangely calming...</td>', 'Nice abstract. Strangely calming...', '2010-10-01 09:17:14.000000', NULL, 1),
(6176780, 910871, 114233, '<td valign="top">Nice idea. Eyes have to move to all the shots seen. Composition of the actual negative shots could be better though - a tighter crop haha</td>', 'Nice idea. Eyes have to move to all the shots seen. Composition of the actual negative shots could be better though - a tighter crop haha', '2010-10-01 09:19:09.000000', NULL, 1),
(6176781, 911744, 114233, '<td valign="top">Stands out very nicely. Composition feels a touch too centred for me though</td>', 'Stands out very nicely. Composition feels a touch too centred for me though', '2010-10-01 09:20:06.000000', NULL, 1),
