(6176783, 911074, 114233, '<td valign="top">This image really looks menacing in negative! Clarity is good but possibly would have been better with the female spider in focus too?</td>', 'This image really looks menacing in negative! Clarity is good but possibly would have been better with the female spider in focus too?', '2010-10-01 09:23:03.000000', NULL, 1),
(6176785, 911762, 114233, '<td valign="top">Would it have been better with a tighter crop on the left so you didnt cut the chair in half? The sky looks really good but maybe not enough sand is shown given your title</td>', 'Would it have been better with a tighter crop on the left so you didnt cut the chair in half? The sky looks really good but maybe not enough sand is shown given your title', '2010-10-01 09:25:00.000000', NULL, 1),
