(6178449, 911552, 36914, '<td valign="top">Like the negative black and white</td>', 'Like the negative black and white', '2010-10-02 18:18:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6178451, 911333, 36914, '<td valign="top">Yellow alittle blowen out, nicely focused.  Love the composition</td>', 'Yellow alittle blowen out, nicely focused.  Love the composition', '2010-10-02 18:20:47.000000', NULL, 1),
(6178453, 910871, 36914, '<td valign="top">Some of these are actually still around.  This is an interesting Interpretation of the challenge. kind of cool that when you turned the<br/>photo shop from positive to negative it did change the negative to almost a positive.</td>', 'Some of these are actually still around.  This is an interesting Interpretation of the challenge. kind of cool that when you turned thephoto shop from positive to negative it did change the negative to almost a positive.', '2010-10-02 18:23:40.000000', NULL, 1),
(6178454, 911365, 36914, '<td valign="top">Needs better focus on the subject,</td>', 'Needs better focus on the subject,', '2010-10-02 18:25:46.000000', NULL, 1),
(6178459, 911381, 121916, '<td valign="top">Incredible details in this.  Excellent composition.</td>', 'Incredible details in this.  Excellent composition.', '2010-10-02 18:27:31.000000', NULL, 1),
(6178460, 911780, 121916, '<td valign="top">Effective and engaging composition.</td>', 'Effective and engaging composition.', '2010-10-02 18:28:16.000000', NULL, 1),
(6178461, 911761, 121916, '<td valign="top">The graphic quality of this is a strong point for this.</td>', 'The graphic quality of this is a strong point for this.', '2010-10-02 18:29:18.000000', NULL, 1),
(6178462, 911575, 36914, '<td valign="top">Changing to Negative makes this look like a true 1800s B/W photo Nicely done.<br/>maybe a little better focus or a lower ASA, it looks a little to grainy</td>', 'Changing to Negative makes this look like a true 1800s B/W photo Nicely done.maybe a little better focus or a lower ASA, it looks a little to grainy', '2010-10-02 18:29:26.000000', NULL, 1),
(6178463, 911552, 121916, '<td valign="top">This has a nice dream-like quality about it.  Most pleasing to the eye.</td>', 'This has a nice dream-like quality about it.  Most pleasing to the eye.', '2010-10-02 18:29:57.000000', NULL, 1),
(6178464, 911085, 36914, '<td valign="top">Inverse of War Freedom, pretty good sharp photo,</td>', 'Inverse of War Freedom, pretty good sharp photo,', '2010-10-02 18:30:49.000000', NULL, 1),
(6178465, 910840, 121916, '<td valign="top">This could have stepped out of an art deco poster.  The color combination is very effective. The contrast between the natural and the man made adds interest to this image.</td>', 'This could have stepped out of an art deco poster.  The color combination is very effective. The contrast between the natural and the man made adds interest to this image.', '2010-10-02 18:31:04.000000', NULL, 1),
(6178466, 911182, 121916, '<td valign="top">Perfect color for this.  I like the "hide and seek" quality of the crab.</td>', 'Perfect color for this.  I like the "hide and seek" quality of the crab.', '2010-10-02 18:31:57.000000', NULL, 1),
(6178467, 911785, 36914, '<td valign="top">Could be alittle more focused on the spider, kind of need that there so far has been three spider pictures in the contest.</td>', 'Could be alittle more focused on the spider, kind of need that there so far has been three spider pictures in the contest.', '2010-10-02 18:32:11.000000', NULL, 1),
(6178469, 911698, 121916, '<td valign="top">Surreal landscape, wonderful use of negative space.</td>', 'Surreal landscape, wonderful use of negative space.', '2010-10-02 18:32:29.000000', NULL, 1),
(6178473, 911878, 36914, '<td valign="top">Negative image with all the colors makes this very colorful picture seems a little out of balance kind of tilted to the right.</td>', 'Negative image with all the colors makes this very colorful picture seems a little out of balance kind of tilted to the right.', '2010-10-02 18:33:23.000000', NULL, 1),
(6178475, 911789, 121916, '<td valign="top">Wonderfully imaginative composition.</td>', 'Wonderfully imaginative composition.', '2010-10-02 18:33:34.000000', NULL, 1),
(6178476, 911778, 121916, '<td valign="top">This really draws the eye in.  The vanishing point is perfectly placed.</td>', 'This really draws the eye in.  The vanishing point is perfectly placed.', '2010-10-02 18:34:48.000000', NULL, 1),
(6178477, 911888, 121916, '<td valign="top">I like the effect of the mono against the color in this.  The details on the statue are quite good.</td>', 'I like the effect of the mono against the color in this.  The details on the statue are quite good.', '2010-10-02 18:34:58.000000', NULL, 1),
(6178479, 911265, 121916, '<td valign="top">The over exposed center is too much for this.</td>', 'The over exposed center is too much for this.', '2010-10-02 18:36:02.000000', NULL, 1),
(6178480, 911145, 121916, '<td valign="top">Has a wonderful oriental feel about it.  The DOF is interesting too.</td>', 'Has a wonderful oriental feel about it.  The DOF is interesting too.', '2010-10-02 18:36:51.000000', NULL, 1),
(6178481, 911856, 121916, '<td valign="top">Powerful!</td>', 'Powerful!', '2010-10-02 18:37:08.000000', NULL, 1),
(6178482, 910878, 121916, '<td valign="top">Unique subject, well handled.</td>', 'Unique subject, well handled.', '2010-10-02 18:38:45.000000', NULL, 1),
(6178483, 911822, 121916, '<td valign="top">The divided face doesn''t translate well in negative for me.</td>', 'The divided face doesn''t translate well in negative for me.', '2010-10-02 18:39:22.000000', NULL, 1),
(6178484, 911714, 121916, '<td valign="top">Simple and effective composition.  Great use of the curving line.</td>', 'Simple and effective composition.  Great use of the curving line.', '2010-10-02 18:39:54.000000', NULL, 1),
(6178486, 911849, 121916, '<td valign="top">Seems to be somewhat crooked, but a fine concept.</td>', 'Seems to be somewhat crooked, but a fine concept.', '2010-10-02 18:41:00.000000', NULL, 1),
(6178487, 910903, 121916, '<td valign="top">Nice use of shadow here.  Subtle light changes.</td>', 'Nice use of shadow here.  Subtle light changes.', '2010-10-02 18:41:37.000000', NULL, 1),
(6178488, 911528, 121916, '<td valign="top">This is busy in a very good way.  The eye literally dances through this image.</td>', 'This is busy in a very good way.  The eye literally dances through this image.', '2010-10-02 18:42:35.000000', NULL, 1),
(6178489, 911525, 121916, '<td valign="top">A seductive abstract.  Well done.</td>', 'A seductive abstract.  Well done.', '2010-10-02 18:43:26.000000', NULL, 1),
(6178490, 911606, 121916, '<td valign="top">The varying tones work well in this.</td>', 'The varying tones work well in this.', '2010-10-02 18:43:57.000000', NULL, 1),
(6178491, 911783, 36914, '<td valign="top">Interesting perspective, looks like he is running along the side of a bulding.  The subject could be a little more in focus looks like the focus read the lines on the building and not the main subject. Nicely done though.</td>', 'Interesting perspective, looks like he is running along the side of a bulding.  The subject could be a little more in focus looks like the focus read the lines on the building and not the main subject. Nicely done though.', '2010-10-02 18:44:16.000000', NULL, 1),
(6178492, 910896, 121916, '<td valign="top">Humorously unusual.  Great capture.</td>', 'Humorously unusual.  Great capture.', '2010-10-02 18:44:29.000000', NULL, 1),
(6178493, 911302, 121916, '<td valign="top">I would have liked it better without the blue ridge, but an effective subject.</td>', 'I would have liked it better without the blue ridge, but an effective subject.', '2010-10-02 18:45:04.000000', NULL, 1),
(6178494, 911198, 121916, '<td valign="top">This is a beautiful use of repetitive shapes.</td>', 'This is a beautiful use of repetitive shapes.', '2010-10-02 18:45:33.000000', NULL, 1),
(6178495, 911262, 121916, '<td valign="top">Visually delightful.</td>', 'Visually delightful.', '2010-10-02 18:45:46.000000', NULL, 1),
(6178497, 911003, 36914, '<td valign="top">The speck in the middle kind of distracted from the full efect of the picture. It will be interesting to see what the original was.</td>', 'The speck in the middle kind of distracted from the full efect of the picture. It will be interesting to see what the original was.', '2010-10-02 18:46:11.000000', NULL, 1),
(6178498, 911223, 121916, '<td valign="top">I like the comp, but I think the speck in the left quadrant might be better removed.</td>', 'I like the comp, but I think the speck in the left quadrant might be better removed.', '2010-10-02 18:46:20.000000', NULL, 1),
(6178499, 911685, 36914, '<td valign="top">Nice</td>', 'Nice', '2010-10-02 18:46:22.000000', NULL, 1),
(6178500, 911463, 121916, '<td valign="top">Definitely different...and very eye catching.</td>', 'Definitely different...and very eye catching.', '2010-10-02 18:47:37.000000', NULL, 1),
(6178501, 910902, 36914, '<td valign="top">Red is just too sharp, hard to look at.  Would fit more as Pop Art.</td>', 'Red is just too sharp, hard to look at.  Would fit more as Pop Art.', '2010-10-02 18:47:45.000000', NULL, 1),
(6178503, 911849, 36914, '<td valign="top">Like the even lines, this is well balanced nice shot.</td>', 'Like the even lines, this is well balanced nice shot.', '2010-10-02 18:48:46.000000', NULL, 1),
(6178647, 910840, 97225, '<td valign="top">I think that this is my favourite in this challenge. I love those trees and the rest of it is intriguing. I''m trying to work it out in my mind what the original looked like - particularly the black area. I''m bumping it from the 9 I gave it to a 10.</td>', 'I think that this is my favourite in this challenge. I love those trees and the rest of it is intriguing. I''m trying to work it out in my mind what the original looked like - particularly the black area. I''m bumping it from the 9 I gave it to a 10.', '2010-10-02 22:55:39.000000', NULL, 1),
(6178702, 911589, 4767, '<td valign="top">nice capture-good processing. I was at McConkie Ranch in early September.  amazing petroglyphs!  Well done!</td>', 'nice capture-good processing. I was at McConkie Ranch in early September.  amazing petroglyphs!  Well done!', '2010-10-02 23:59:31.000000', NULL, 1),
(6178704, 910896, 4767, '<td valign="top">And frightened miss Muffett away?  Nice creativity.</td>', 'And frightened miss Muffett away?  Nice creativity.', '2010-10-03 00:03:42.000000', NULL, 1),
(6178817, 911789, 101702, '<td valign="top">Is this the negative or the positive? Initially I felt this was the positive, and that it DNMC. I then re-read the challenge brief and it says "an image that works well as a negative" so not necessarily entered as a negative. So, ok, meets the challenge. I then ran a negative conversion on it, and the image is still very effective. I still can''t decide which is positive and negative, and therefore realise that the image is genious. I''ve spent more time looking at and analysing this image, so from my initial thoughts of DNMC, I''m now thinking this is a ribbon contender!</td>', 'Is this the negative or the positive? Initially I felt this was the positive, and that it DNMC. I then re-read the challenge brief and it says "an image that works well as a negative" so not necessarily entered as a negative. So, ok, meets the challenge. I then ran a negative conversion on it, and the image is still very effective. I still can''t decide which is positive and negative, and therefore realise that the image is genious. I''ve spent more time looking at and analysing this image, so from my initial thoughts of DNMC, I''m now thinking this is a ribbon contender!', '2010-10-03 05:06:34.000000', NULL, 1),
(6178831, 910871, 101702, '<td valign="top">Nice idea. Frame feels a bit busy though... maybe 1 strip would have been more impactive</td>', 'Nice idea. Frame feels a bit busy though... maybe 1 strip would have been more impactive', '2010-10-03 05:15:55.000000', NULL, 1),
(6178836, 911664, 101702, '<td valign="top">I find the half street sign at the bottom really distracting. Either getting the whole sign in, or cropping it all out would be an improvement in my opinion.</td>', 'I find the half street sign at the bottom really distracting. Either getting the whole sign in, or cropping it all out would be an improvement in my opinion.', '2010-10-03 05:18:23.000000', NULL, 1),
(6179156, 911197, 27812, '<td valign="top">I notice serious banding/noise. If you sharpen using the LAB color space in Photoshop, sharpen the L channel and you then Gaussian blur the A and B channels with a blur of 5/ radius 1, you will see a totally different pix.</td>', 'I notice serious banding/noise. If you sharpen using the LAB color space in Photoshop, sharpen the L channel and you then Gaussian blur the A and B channels with a blur of 5/ radius 1, you will see a totally different pix.', '2010-10-03 12:53:00.000000', NULL, 1),
(6179186, 911815, 27812, '<td valign="top">If it was not for the awful 2 sided so called border, it would have been a 10. I love your picture!!!</td>', 'If it was not for the awful 2 sided so called border, it would have been a 10. I love your picture!!!', '2010-10-03 13:08:23.000000', NULL, 1),
(6179438, 911826, 9576, '<td valign="top">Excellent image</td>', 'Excellent image', '2010-10-03 16:59:11.000000', NULL, 1),
