(6179462, 911463, 9576, '<td valign="top">great image well made 10</td>', 'great image well made 10', '2010-10-03 17:12:34.000000', NULL, 1),
(6179514, 911263, 114225, '<td valign="top">Great use of the negative technique to turn an interesting subject into an extraordinary subject!</td>', 'Great use of the negative technique to turn an interesting subject into an extraordinary subject!', '2010-10-03 18:20:48.000000', NULL, 1),
(6179516, 911762, 114225, '<td valign="top">Interesting choice for this challenge. This looks like it would be such  beautiful photo in normal view, but as negative, it loses its oomph.</td>', 'Interesting choice for this challenge. This looks like it would be such  beautiful photo in normal view, but as negative, it loses its oomph.', '2010-10-03 18:21:32.000000', NULL, 1),
(6179518, 911821, 114225, '<td valign="top">I think the best goal for this challenge it is find a subject that is enhanced by the negative color technique. Unfortunately, I don''t think this one works well there, as nothing looks negative or enhanced.</td>', 'I think the best goal for this challenge it is find a subject that is enhanced by the negative color technique. Unfortunately, I don''t think this one works well there, as nothing looks negative or enhanced.', '2010-10-03 18:22:31.000000', NULL, 1),
(6179521, 911678, 114225, '<td valign="top">Nice use of the negative color technique to increase the interest in this photo. I could see this making a very good desktop backgorund</td>', 'Nice use of the negative color technique to increase the interest in this photo. I could see this making a very good desktop backgorund', '2010-10-03 18:23:20.000000', NULL, 1),
(6179524, 911804, 114225, '<td valign="top">Freaky, yet cool. The negative technique gave this photo a very radioactive feel, something you don''t see everyday.</td>', 'Freaky, yet cool. The negative technique gave this photo a very radioactive feel, something you don''t see everyday.', '2010-10-03 18:24:04.000000', NULL, 1),
(6179527, 911767, 114225, '<td valign="top">Very cool use of the negative color technique. All the colors in the feathers is really what makes this interesting.</td>', 'Very cool use of the negative color technique. All the colors in the feathers is really what makes this interesting.', '2010-10-03 18:24:45.000000', NULL, 1),
(6179530, 911542, 114225, '<td valign="top">Nice photo. I like the composition and crop used. The negative is used well here to add uniqueness.</td>', 'Nice photo. I like the composition and crop used. The negative is used well here to add uniqueness.', '2010-10-03 18:25:32.000000', NULL, 1),
(6179534, 911069, 114225, '<td valign="top">Interesting idea, it has a good amount of potential. I''m not really liking the blue silhouette, it''s taking away from the main subject. With less pixelation in the edges, this could have been really cool.</td>', 'Interesting idea, it has a good amount of potential. I''m not really liking the blue silhouette, it''s taking away from the main subject. With less pixelation in the edges, this could have been really cool.', '2010-10-03 18:26:58.000000', NULL, 1),
(6179536, 911333, 114225, '<td valign="top">Very nice abstract. The negative colors add to the interest here (mainly in making us guess at what''s being photographed).</td>', 'Very nice abstract. The negative colors add to the interest here (mainly in making us guess at what''s being photographed).', '2010-10-03 18:27:48.000000', NULL, 1),
(6179537, 911198, 114225, '<td valign="top">Great use of negative here. Gives a unique view on the standard fern leaf. Also good composition and crop.</td>', 'Great use of negative here. Gives a unique view on the standard fern leaf. Also good composition and crop.', '2010-10-03 18:28:38.000000', NULL, 1),
(6179539, 911876, 114225, '<td valign="top">Very nice. The sharp focus to this shot is really key. The blue cast adds intrigue.</td>', 'Very nice. The sharp focus to this shot is really key. The blue cast adds intrigue.', '2010-10-03 18:30:05.000000', NULL, 1),
(6179540, 911854, 114225, '<td valign="top">Interesting idea with a reverse silhouette. I like it.</td>', 'Interesting idea with a reverse silhouette. I like it.', '2010-10-03 18:30:49.000000', NULL, 1),
(6179543, 911869, 114225, '<td valign="top">I''m guessing this isn''t doing well, but I like it. It could use a bit less noise, and it would have been really cool to see some detail in the moon, but still cool.</td>', 'I''m guessing this isn''t doing well, but I like it. It could use a bit less noise, and it would have been really cool to see some detail in the moon, but still cool.', '2010-10-03 18:32:35.000000', NULL, 1),
(6179547, 911599, 114225, '<td valign="top">Well done. The mix of colors in the sky adds interest, and the sharp outline of the moon really helps the shot.</td>', 'Well done. The mix of colors in the sky adds interest, and the sharp outline of the moon really helps the shot.', '2010-10-03 18:34:35.000000', NULL, 1),
(6179551, 911857, 114225, '<td valign="top">Good use of the negative technique to turn something that would be somewhat boring into something interesting.</td>', 'Good use of the negative technique to turn something that would be somewhat boring into something interesting.', '2010-10-03 18:36:49.000000', NULL, 1),
(6179553, 910837, 114225, '<td valign="top">Cool idea with the glasses. Not sure how I feel about the mouth position.</td>', 'Cool idea with the glasses. Not sure how I feel about the mouth position.', '2010-10-03 18:37:37.000000', NULL, 1),
(6179555, 911717, 114225, '<td valign="top">Interesting colors. It;s like magic how the purple liquid is pouring out blue.</td>', 'Interesting colors. It;s like magic how the purple liquid is pouring out blue.', '2010-10-03 18:38:13.000000', NULL, 1),
(6179559, 911698, 114225, '<td valign="top">Very cool. Great way to turn an interesting scene into a mysterious scene.</td>', 'Very cool. Great way to turn an interesting scene into a mysterious scene.', '2010-10-03 18:39:33.000000', NULL, 1),
(6179563, 911783, 114225, '<td valign="top">Very cool Tron look to this photo.</td>', 'Very cool Tron look to this photo.', '2010-10-03 18:41:14.000000', NULL, 1),
(6179570, 910871, 114225, '<td valign="top">Great idea! Nice job with the overlapping of subjects and using the negative processing to bring out the true color in the images.</td>', 'Great idea! Nice job with the overlapping of subjects and using the negative processing to bring out the true color in the images.', '2010-10-03 18:44:13.000000', NULL, 1),
(6179669, 911895, 50864, '<td valign="top">My favorite in the challenge. 10</td>', 'My favorite in the challenge. 10', '2010-10-03 19:50:29.000000', NULL, 1),
(6179670, 911812, 50864, '<td valign="top">Beautiful. 9</td>', 'Beautiful. 9', '2010-10-03 19:50:55.000000', NULL, 1),
