(6182316, 911248, 104809, '<td valign="top">Awesome.  I love the effect of light coming through from behind and the dark contrast of leaves.</td>', 'Awesome.  I love the effect of light coming through from behind and the dark contrast of leaves.', '2010-10-05 20:55:00.000000', NULL, 1),
(6182319, 911867, 104809, '<td valign="top">Beautiful colors.  I love the purples and vibrant edges on some of the leaves.</td>', 'Beautiful colors.  I love the purples and vibrant edges on some of the leaves.', '2010-10-05 20:55:11.000000', NULL, 1),
(6182320, 911552, 104809, '<td valign="top">Nice.  I like the grainy textures and how the background fades into the "fog".</td>', 'Nice.  I like the grainy textures and how the background fades into the "fog".', '2010-10-05 20:55:13.000000', NULL, 1),
(6182321, 911155, 104809, '<td valign="top">Beautiful.  I like how it looks like a watercolor painting.</td>', 'Beautiful.  I like how it looks like a watercolor painting.', '2010-10-05 20:55:17.000000', NULL, 1),
(6182322, 911856, 104809, '<td valign="top">Ooooh... beautiful colors and the glowing eye.</td>', 'Ooooh... beautiful colors and the glowing eye.', '2010-10-05 20:55:18.000000', NULL, 1),
(6182323, 911603, 104809, '<td valign="top">Beautiful colors brought out of the needles.</td>', 'Beautiful colors brought out of the needles.', '2010-10-05 20:55:26.000000', NULL, 1),
(6182325, 911074, 104809, '<td valign="top">I like this.  I liked the sense of "uh oh" I got while my eyes moved from the foreground critter to seeing the "hidden" background.  I really like the effect of the DoF here.</td>', 'I like this.  I liked the sense of "uh oh" I got while my eyes moved from the foreground critter to seeing the "hidden" background.  I really like the effect of the DoF here.', '2010-10-05 20:55:43.000000', NULL, 1),
(6182326, 911359, 108069, '<td valign="top">Quite the badass photo. Very cool.</td>', 'Quite the badass photo. Very cool.', '2010-10-05 20:55:44.000000', NULL, 1),
(6182328, 911463, 104809, '<td valign="top">Very nice.</td>', 'Very nice.', '2010-10-05 20:56:45.000000', NULL, 1),
(6182329, 911617, 104809, '<td valign="top">Beautiful details and nice DoF.  I''m a little distracted by the balance of the image, but I''m not sure how to crop it differently, without losing some of the great details you''re showing off.</td>', 'Beautiful details and nice DoF.  I''m a little distracted by the balance of the image, but I''m not sure how to crop it differently, without losing some of the great details you''re showing off.', '2010-10-05 20:57:12.000000', NULL, 1),
(6182331, 911263, 108069, '<td valign="top">Wonderful colors. Amazing the way the negative treatment can draw illumination from the darkness. Perfect subject to display that. Well done.</td>', 'Wonderful colors. Amazing the way the negative treatment can draw illumination from the darkness. Perfect subject to display that. Well done.', '2010-10-05 20:57:20.000000', NULL, 1),
(6182333, 911678, 104809, '<td valign="top">I wish more of this was in focus, but this is still quite superb.  I love this abstract stuff.</td>', 'I wish more of this was in focus, but this is still quite superb.  I love this abstract stuff.', '2010-10-05 20:57:25.000000', NULL, 1),
(6182334, 911078, 104809, '<td valign="top">Nice.  I like the bokeh.</td>', 'Nice.  I like the bokeh.', '2010-10-05 20:57:33.000000', NULL, 1),
(6182335, 911197, 104809, '<td valign="top">I''m not sure if the banding and noise in the background gradient is interesting or distracting.  I''m leaning towards "interesting" at the moment. I like this a lot.</td>', 'I''m not sure if the banding and noise in the background gradient is interesting or distracting.  I''m leaning towards "interesting" at the moment. I like this a lot.', '2010-10-05 20:57:42.000000', NULL, 1),
(6182336, 911531, 104809, '<td valign="top">Interesting contrasts between the foreground and background pieces.  The focus shifts and the specular highlights are different, too.  Neat.</td>', 'Interesting contrasts between the foreground and background pieces.  The focus shifts and the specular highlights are different, too.  Neat.', '2010-10-05 20:59:18.000000', NULL, 1),
(6182337, 911449, 104809, '<td valign="top">Nice abstract and cool bokeh.  Treads?</td>', 'Nice abstract and cool bokeh.  Treads?', '2010-10-05 20:59:28.000000', NULL, 1),
(6182339, 911785, 100831, '<td valign="top">I can''t get past the great title.... have to come back to view the photo.<br/>I''m baaaaack and I like what I see!!</td>', 'I can''t get past the great title.... have to come back to view the photo.I''m baaaaack and I like what I see!!', '2010-10-05 21:01:18.000000', NULL, 1);
